    constructor() {
        this.modal = document.getElementById('deleteModal');
        this.trigger = document.querySelector('.trigger');
        this.cancelBtn = document.querySelector('.modal-cancel');
        this.confirmBtn = document.querySelector('.modal-confirm');
        this.closeBtn = document.querySelector('.modal-close');

        this.init();
    }

    init() {
        if (!this.modal || !this.trigger) {
            console.error('Modal or trigger button not found');
            return;
        }

        this.trigger.addEventListener('click', () => this.openModal());
        this.cancelBtn.addEventListener('click', () => this.closeModal());
        this.closeBtn.addEventListener('click', () => this.closeModal());
        this.confirmBtn.addEventListener('click', () => this.handleDelete());

        this.modal.addEventListener('click', (e) => {
            if (e.target === this.modal) {
                this.closeModal();
            }
        });

        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape' && this.isModalOpen()) {
                this.closeModal();
            }
        });
    }

    openModal() {
        this.modal.showModal();
        this.modal.classList.add('open');
        document.body.style.overflow = 'hidden';
    }

    closeModal() {
        this.modal.close();
        this.modal.classList.remove('open');
        document.body.style.overflow = '';
    }

    isModalOpen() {
        return this.modal.open;
    }

    handleDelete() {
        console.log('Image deleted successfully');
        this.closeModal();

        this.showNotification('Image deleted from library');
    }

    showNotification(message) {
        const notification = document.createElement('div');
        notification.className = 'notification';
        notification.textContent = message;
        notification.style.cssText = `
            position: fixed;
            bottom: 2rem;
            right: 2rem;
            background-color: #10b981;
            color: white;
            padding: 1rem 1.5rem;
            border-radius: 8px;
            box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
            animation: slideIn 0.3s ease;
            z-index: 1001;
        `;

        const style = document.createElement('style');
        style.textContent = `
            @keyframes slideIn {
                from {
                    opacity: 0;
                    transform: translateX(100%);
                }
                to {
                    opacity: 1;
                    transform: translateX(0);
                }
            }
        `;
        document.head.appendChild(style);
        document.body.appendChild(notification);

        setTimeout(() => {
            notification.remove();
        }, 3000);
    }
}

document.addEventListener('DOMContentLoaded', () => {
    new ImagePreviewModal();
});
